        if (hand == InteractionHand.MAIN_HAND && this.isDualWieldingTridents(entityPatch)) {
            this.renderOffhandTrident(entityPatch, poses, buffer, poseStack, packedLight, partialTicks);
        }
    }

    private boolean isDualWieldingTridents(LivingEntityPatch<?> entityPatch) {
        CapabilityItem mainhandCap;
        ItemStack mainhandStack = ((LivingEntity)entityPatch.getOriginal()).m_21205_();
        ItemStack offhandStack = ((LivingEntity)entityPatch.getOriginal()).m_21206_();
        if (mainhandStack.m_41720_() == Items.f_42713_ && offhandStack.m_41720_() == Items.f_42713_ && (mainhandCap = EpicFightCapabilities.getItemStackCapability((ItemStack)mainhandStack)) instanceof TridentCapabilityX) {
            TridentCapabilityX tridentCap = (TridentCapabilityX)mainhandCap;
            return tridentCap.getStyle(entityPatch) == CapabilityItem.Styles.TWO_HAND;
        }
        return false;
    }

    private void renderOffhandTrident(LivingEntityPatch<?> entityPatch, OpenMatrix4f[] poses, MultiBufferSource buffer, PoseStack poseStack, int packedLight, float partialTicks) {
